command:
const combat = game.combats.find(c => c.isActive);
if (!combat?.started) {
    ui.notifications.warn(game.i18n.localize("FQCARDENGINE.MacroErrorMsgEndTurnOutOfCombat"));
} else if (!game.user.isGM && combat.combatant?.actor?.id !== game.user.character?.id) {
    ui.notifications.warn(game.i18n.localize("FQCARDENGINE.MacroErrorMsgEndTurnNotYourTurn"));
} else {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: darkgreen;">${game.i18n.format("FQCARDENGINE.MacroMsgEndTurn", {actorName: combat.combatant?.actor?.name ?? ""})}</h3>`
    });
    await combat.nextTurn();
}
